package neuralframework

import (
	"encoding/json"
	"math"
	"os"
	"reflect"
	"testing"
)

// Fixtures are independent hand arithmetic, not outputs generated by this port.
func fixture(t *testing.T, name string, target any) {
	t.Helper()
	data, err := os.ReadFile("../../../specs/fixtures/neural-framework-v1/" + name)
	if err != nil {
		t.Fatal(err)
	}
	if err = json.Unmarshal(data, target); err != nil {
		t.Fatal(err)
	}
}
func closeNumber(t *testing.T, a, b, tol float64) {
	t.Helper()
	if math.IsNaN(a) || math.Abs(a-b) > tol {
		t.Fatalf("%g != %g", a, b)
	}
}
func closeGrid(t *testing.T, a, b Grid, tol float64) {
	t.Helper()
	if len(a) != len(b) {
		t.Fatal("rows")
	}
	for i := range a {
		if len(a[i]) != len(b[i]) {
			t.Fatal("cols")
		}
		for j := range a[i] {
			closeNumber(t, a[i][j], b[i][j], tol)
		}
	}
}
func must(t *testing.T, n *Network, e error) *Network {
	t.Helper()
	if e != nil {
		t.Fatal(e)
	}
	return n
}
func TestPaper(t *testing.T) {
	var f struct {
		Paper struct {
			Checkpoint                   Checkpoint
			Inputs, Targets, Predictions Grid
			Loss                         float64
			Rate                         float64     `json:"learning_rate"`
			DW                           []Grid      `json:"weight_gradients"`
			DB                           [][]float64 `json:"bias_gradients"`
			Updated                      Checkpoint  `json:"updated_checkpoint"`
			UpdatedPred                  Grid        `json:"updated_predictions"`
			UpdatedLoss                  float64     `json:"updated_loss"`
		}
		Seed struct {
			Value       uint32
			Widths      []int
			Activations []Activation
			Weights     Grid `json:"first_weights"`
		}
	}
	fixture(t, "dense.json", &f)
	p := f.Paper
	n, e := FromCheckpoint(p.Checkpoint)
	n = must(t, n, e)
	g, e := n.Gradients(p.Inputs, p.Targets)
	if e != nil {
		t.Fatal(e)
	}
	closeGrid(t, g.Predictions, p.Predictions, 1e-12)
	closeNumber(t, g.Loss, p.Loss, 1e-12)
	for l := range g.WeightGradients {
		closeGrid(t, g.WeightGradients[l], p.DW[l], 1e-12)
		closeGrid(t, Grid{g.BiasGradients[l]}, Grid{p.DB[l]}, 1e-12)
	}
	history, e := n.Fit(p.Inputs, p.Targets, 1, p.Rate)
	if e != nil {
		t.Fatal(e)
	}
	closeNumber(t, history[1], p.UpdatedLoss, 1e-12)
	got := n.ToCheckpoint()
	for l := range got.Layers {
		closeGrid(t, got.Layers[l].Weights, p.Updated.Layers[l].Weights, 1e-12)
		closeGrid(t, Grid{got.Layers[l].Biases}, Grid{p.Updated.Layers[l].Biases}, 1e-12)
	}
	pred, e := n.Predict(p.Inputs)
	if e != nil {
		t.Fatal(e)
	}
	closeGrid(t, pred, p.UpdatedPred, 1e-12)
	if n.Step() != 1 {
		t.Fatal("step")
	}
	seeded, e := Seeded(f.Seed.Widths, f.Seed.Activations, f.Seed.Value)
	seeded = must(t, seeded, e)
	closeGrid(t, seeded.ToCheckpoint().Layers[0].Weights, f.Seed.Weights, 1e-12)
}
func TestSharedCorpus(t *testing.T) {
	var c struct {
		Contract string
		Cases    []struct {
			ID         string
			Accept     bool
			Checkpoint json.RawMessage
		}
	}
	fixture(t, "checkpoints.json", &c)
	if c.Contract != "NN40" || len(c.Cases) != 55 {
		t.Fatal("inventory")
	}
	ids := map[string]bool{}
	nullCases := map[string]bool{
		"null-weight-cell": false, "null-weight-cell-mixed": false,
		"null-bias-cell": false, "null-bias-cell-mixed": false,
		"null-weight-cell-later-layer": false, "null-bias-cell-later-layer": false,
	}
	accepted := 0
	for _, v := range c.Cases {
		t.Run(v.ID, func(t *testing.T) {
			if v.ID == "" || ids[v.ID] {
				t.Fatal("id")
			}
			ids[v.ID] = true
			if _, required := nullCases[v.ID]; required {
				if v.Accept {
					t.Fatal("NN43 numeric null must reject")
				}
				nullCases[v.ID] = true
			}
			n, e := FromJSON(v.Checkpoint)
			if (e == nil) != v.Accept {
				t.Fatalf("decision %v", e)
			}
			if v.Accept {
				accepted++
				data, e := n.ToJSON()
				if e != nil {
					t.Fatal(e)
				}
				again, e := FromJSON(data)
				again = must(t, again, e)
				if !reflect.DeepEqual(again.ToCheckpoint(), n.ToCheckpoint()) {
					t.Fatal("round trip")
				}
			}
		})
	}
	if accepted != 3 {
		t.Fatal("controls")
	}
	for id, seen := range nullCases {
		if !seen {
			t.Fatalf("missing NN43 case %s", id)
		}
	}
}
